      id: 'arequipa-sol-de-mayo', city: 'arequipa', category: 'food', lat: -16.3893, lng: -71.5459, image: '700ghzQmagU',
      rating: 4.5, reviews: 8100, tags: ['food', 'culture'], price: { kind: 'level', level: 2 }, hours: 'daily 11:00–18:00',
      address: 'Jerusalén 207, Yanahuara, Arequipa',
      text: {
        ru: { name: 'Sol de Mayo', description: 'Известная пикантерия в Янауаре с садом и тенистым двором, где подают классику арекипской кухни: рокото-релено (фаршированный острый перец), чупе-де-камаронес и адобо. Работает только днём.', tip: 'Закажите рокото-релено и чупе-де-камаронес; приходите в 12:30 или после 15:00, чтобы не стоять в очереди. Платят картой и наличными.' },
        en: { name: 'Sol de Mayo', description: 'A well-known picantería in Yanahuara with a garden and shaded courtyard serving the classics of Arequipa cooking: rocoto relleno (stuffed hot pepper), chupe de camarones and adobo. It is open for lunch only.', tip: 'Order the rocoto relleno and the chupe de camarones; arrive at 12:30 or after 3 pm to avoid the queue. Cards and cash accepted.' },
        es: { name: 'Sol de Mayo', description: 'Una conocida picantería en Yanahuara, con jardín y patio sombreado, que sirve los clásicos de la cocina arequipeña: rocoto relleno, chupe de camarones y adobo. Solo abre al mediodía.', tip: 'Pide el rocoto relleno y el chupe de camarones; llega a las 12:30 o después de las 15:00 para evitar la cola. Aceptan tarjeta y efectivo.' },
        de: { name: 'Sol de Mayo', description: 'Eine bekannte Picantería in Yanahuara mit Garten und schattigem Innenhof, die die Klassiker der Küche von Arequipa serviert: Rocoto relleno (gefüllte scharfe Paprika), Chupe de Camarones und Adobo. Geöffnet ist nur mittags.', tip: 'Bestell den Rocoto relleno und den Chupe de Camarones; komm um 12:30 Uhr oder nach 15 Uhr, um die Schlange zu meiden. Karte und Bargeld werden akzeptiert.' },
        fr: { name: 'Sol de Mayo', description: 'Une picantería réputée de Yanahuara, avec jardin et cour ombragée, qui sert les classiques de la cuisine d’Arequipa : rocoto relleno (piment farci), chupe de camarones et adobo. Elle n’est ouverte qu’à midi.', tip: 'Commandez le rocoto relleno et le chupe de camarones ; arrivez à 12 h 30 ou après 15 h pour éviter la file. Cartes et espèces acceptées.' },
        it: { name: 'Sol de Mayo', description: 'Una nota picantería a Yanahuara con giardino e cortile ombreggiato che serve i classici della cucina di Arequipa: rocoto relleno (peperone piccante ripieno), chupe de camarones e adobo. È aperta solo a pranzo.', tip: 'Ordina il rocoto relleno e il chupe de camarones; arriva alle 12:30 o dopo le 15 per evitare la coda. Si paga con carta o contanti.' },
      },
